[CmdletBinding()] param([string]$ResourceName,[string]$ResourceType,[Parameter(Mandatory)][string]$ResourceGroup,[Parameter(Mandatory)][string]$OutputDirectory,[string]$Subscription)
. (Join-Path $PSScriptRoot 'Common-AzureCollector.ps1');$doc=New-CollectorDocument $ResourceType $ResourceName $ResourceGroup $Subscription
$ws=Invoke-AzCommandJson 'monitor.log-analytics.workspace.show' @('monitor','log-analytics','workspace','show','--workspace-name',$ResourceName,'--resource-group',$ResourceGroup) $Subscription -Required;Add-CollectorSection $doc 'show' $ws;if($ws.data.id){Add-StandardResourceEvidence $doc $ws.data.id $Subscription};$file=Join-Path $OutputDirectory ('log-analytics-{0}.json' -f (ConvertTo-CollectorSafeFileName $ResourceName));Save-CollectorDocument $doc $file;[pscustomobject]@{resourceType='logAnalytics';name=$ResourceName;outputFile=$file}